try:
    import datetime
    b = config.get('body') if isinstance(config, dict) else None
    if isinstance(b, dict) and vars.get('deadline_iso'):
        if vars.get('product_id'):
            b['product_id'] = vars.get('product_id')
        if vars.get('promise_ok') == 'yes':
            err = 'A promise is already recorded for this product. It cannot be changed or recorded again in this call.'
        else:
            H = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
            a = float(b.get('amount'))
            ds = str(b.get('date'))[:10]
            d = datetime.date.fromisoformat(ds)
            if a < float(vars.get('floor_amt')) - 0.005:
                err = 'Amount is below the floor. It cannot be recorded. Offer the floor.'
            elif a > float(vars.get('full_amt')) + 0.005:
                err = 'Amount is above the full past-due amount. Propose the full past-due amount.'
            elif ds < str(vars.get('today_iso')):
                err = 'Date is before today.'
            elif ds > str(vars.get('deadline_iso')):
                err = 'Date is after the deadline. Offer the deadline.'
            elif d.weekday() > 4 or ds in H:
                err = 'Date is not a business day. Offer the next business day.'
except Exception as e:
    err = 'BLOCKED: amount must be a number and date must be YYYY-MM-DD.'
if not err:
    try:
        vars['promise_tries'] = int(float(vars.get('promise_tries') or 0)) + 1
    except Exception:
        pass
if err:
    vars['promise_blocked'] = err
    raise ValueError('BLOCKED, nothing was recorded: ' + err + ' Fix it with the customer, read it back again and get a clear yes before calling create_promise again.')

